function slug(s) {
  return s.toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-|-$/g, "");
}

function ex(ch, n, name, title, format, domain, audience, stakes, requiredBeat, scenario, whatToDo, whyItMatters, tags) {
  return {
    exampleId: `ch${String(ch).padStart(2, "0")}-ex${String(n).padStart(2, "0")}-${slug(title).slice(0, 36)}`,
    title,
    tags,
    planSpec: { domain, audience, stakes, format, requiredBeat },
    scenario,
    whatToDo,
    whyItMatters,
  };
}

function makeBreakdown(c) {
  const fast = `${c.fastScene}\n\n${c.fastRule}\n\n${c.fastMove}`;
  const deep = `${c.deepScene}\n\n${c.deepMechanism}\n\n${c.deepMove}\n\n${c.deepLimit}\n\nPicture the next live choice. The cue will not announce itself as a bias. It will arrive as a price, a label, a free offer, a public answer, or a feeling that the answer is already clear. Pause there. Name the cue in ordinary words. Then ask what you would choose if that cue had arrived later, or not at all.\n\nA good test is small and physical. Cover the label. Hide the price. Write the first number on a separate page. Ask for private votes. Put the rule at the top of the form. The mind changes when the room changes, so change the room before asking yourself to be heroic.`;
  const full = `${c.fullScene}\n\n${c.fullMechanism}\n\n${c.fullSecond}\n\n${c.fullObjection}\n\n${c.fullMove}\n\n${c.fullLimit}\n\nPicture a second person watching the same scene from the doorway. That person does not feel the same pull. The suite is just a room, the token is just five dollars, the old truck is just metal and rust, the first public order is just one voice. That outside view is useful because it shows how much of the choice lives in the setup, not in the object itself.\n\nYou can borrow that outside view without becoming cold. Write the choice in two columns. In the first column, put the thing itself: dose, miles, price, time, taste, deadline, buyer value, cash value, private preference. In the second column, put the cue that arrived around it: free, expensive, already mine, first, public, praised, easy to hide, nearly as good as the costly option. The split does not choose for you. It shows which part of the feeling belongs to the thing and which part belongs to the frame.\n\nA designer would not lecture the person in the scene. A designer would change the order of events. The pledge comes before the answer key. The private vote comes before the boss speaks. The grocery list comes before hunger. The buyer's view comes before the asking price. The hidden cost comes before the word free. Better choices often come from moving one sentence, one form field, or one object a few minutes earlier.\n\nThis is also why shame is a weak tool here. People do not need to feel foolish for being moved by frames. Frames work because they use normal shortcuts: compare nearby things, trust first numbers, avoid losses, follow social signals, and preserve a decent picture of yourself. The practical move is humbler and stronger. Expect the shortcut, then arrange the choice so the shortcut has less room to run.\n\nUse the same question whenever the pull feels too smooth: what changed in the world, and what changed only in the way the world was presented? If the answer is mostly presentation, slow down. If the option still wins after that pause, it has earned more trust.`;
  return { fastRead: fast, deepRead: deep, fullRead: full };
}

function ensureCounter(c) {
  if (/most people/i.test(c.counterintuition) && /but|instead|actually/i.test(c.counterintuition)) {
    return c.counterintuition;
  }
  const lower = c.counterintuition.charAt(0).toLowerCase() + c.counterintuition.slice(1);
  return `Most people assume the first feeling is a clean signal, but actually ${lower}`;
}

function makeQuiz(c, ch) {
  const prompts = [
    `A manager is comparing three vendor bids at 4:10 p.m. One weak bid makes the favorite look clean, even though the team's real need has not changed. Which move best applies ${c.shortIdea}?`,
    `A teacher is about to accept the first grade estimate that popped into her head while scoring essays. If she wants to avoid being pulled by the first number, what should she do next?`,
    `A student is choosing a free seminar that costs two bus rides and a missed lab. Which answer best shows the hidden cost that the price tag has covered up?`,
    `A founder is about to add a small cash bonus to a favor that people have been doing gladly. Which risk should she notice before changing the offer?`,
    `A parent writes a rule for late-night phone use while calm because he knows 11:40 p.m. will feel different. What makes that rule stronger than a promise made later?`,
    `A team keeps every project option alive, and the calendar is full of tiny check-ins. Which plan best fits the lesson in ${c.plainTopic}?`,
    `A seller cannot let go of a used bike because he remembers every repair he made. Which question would best test whether ownership is inflating his price?`,
    `A clinic wants to know whether a high-priced cream truly works better or only feels better. Which test would separate the label from the effect?`,
    `Someone can fudge a gift-card report more easily than a cash box count. What design change would make the moral cost visible before the fudge starts?`,
  ];
  return {
    passingScorePercent: 70,
    questions: prompts.map((prompt, i) => ({
      questionId: `ch${String(ch).padStart(2, "0")}-q${String(i + 1).padStart(2, "0")}`,
      prompt,
      choices: [
        c.quizChoices[i][0],
        c.quizChoices[i][1],
        c.quizChoices[i][2],
      ],
      correctIndex: correct[i],
      explanation: c.quizExplanations[i],
      bloomsLevel: blooms[i],
      depthLevel: depths[i],
    })),
  };
}

function makeCards(c, ch) {
  return [
    {
      cardId: `ch${String(ch).padStart(2, "0")}-rc01`,
      front: `You are staring at a choice that feels obvious only after a new comparison appeared. What do you retrieve first?`,
      back: `Retrieve the frame check: ask which option made the winner look better and whether that comparison belongs in the real decision.`,
      difficulty: "easy",
    },
    {
      cardId: `ch${String(ch).padStart(2, "0")}-rc02`,
      front: `A price, label, or social cue arrives before the evidence. What should you do before trusting your reaction?`,
      back: `Separate the cue from the facts. Cover the label, reset the first number, or make the choice private long enough to see what still fits.`,
      difficulty: "medium",
    },
    {
      cardId: `ch${String(ch).padStart(2, "0")}-rc03`,
      front: `A future version of you will be tired, tempted, or proud. What design move helps that future self?`,
      back: `Build the guardrail while you are calm. Use a deadline, default, lockout, checklist, or private rule before the hot moment edits the story.`,
      difficulty: "medium",
    },
    {
      cardId: `ch${String(ch).padStart(2, "0")}-rc04`,
      front: `A small shortcut feels harmless because the cost is hidden. What question exposes it?`,
      back: `Ask what this would cost if the bill were visible right now: time, trust, money, attention, or the next choice it makes harder.`,
      difficulty: "hard",
    },
  ];
}

function makeImplementation(c) {
  return {
    coreSkill: `${c.coreSkill} The practice is to slow the first confident feeling and change the setting around the choice. You are not trying to become perfectly rational. You are making the hidden cue easier to see before it spends your money, time, trust, or attention.`,
    ifThenPlans: [
      { context: "work", plan: `If a work choice feels obvious after a comparison, price, label, or deadline appears, then I will name that cue in the margin and ask whether it belongs in the decision before I approve anything.` },
      { context: "health", plan: `If I am making a health choice while tired, hungry, keyed up, or embarrassed, then I will use the rule I wrote earlier and delay any optional choice until the next calm window.` },
      { context: "personal", plan: `If a purchase looks better because it is free, discounted, expensive, or already mine, then I will write the real cost and the buyer's view on paper before I keep going.` },
      { context: "relationships", plan: `If money, status, or public image starts changing a favor or shared choice, then I will pause and reset the norm out loud before anyone feels trapped by it.` },
    ],
    twentyFourHourChallenge: `In the next 24 hours, catch one live decision before you finish it. Write the cue that is steering you, such as a first price, free offer, public audience, ownership feeling, or label, then make one small design change that weakens that cue.`,
    weeklyPractice: `Once this week, review three choices you made and mark the hidden cue in each one. For the next similar choice, set a guardrail before the cue shows up.`,
  };
}

function makeMemorable(c) {
  const line = c.line.length >= 30 ? c.line : c.fastRule.split(".")[0] + ".";
  return [
    { text: c.hook, location: "hook", why: "It puts the bias into a concrete object before naming the lesson." },
    { text: c.keyTakeaway, location: "keyTakeaway", why: "It gives the reader one sentence to carry into a live choice." },
    { text: line, location: c.line.length >= 30 ? c.lineLocation : "breakdown.fastRead", why: "It turns the mechanism into a move the reader can picture." },
  ];
}

function makeChapter(c) {
  return {
    chapterId: `predictably-irrational-ch${String(c.number).padStart(2, "0")}`,
    number: c.number,
    title: c.title,
    readingTimeMinutes: 12,
    hook: c.hook,
    counterintuition: ensureCounter(c),
    tryThisNow: c.tryThisNow,
    keyTakeaway: c.keyTakeaway,
    breakdown: makeBreakdown(c),
    examples: c.examples,
    quiz: makeQuiz(c, c.number),
    reviewCards: makeCards(c, c.number),
    implementationPlan: makeImplementation(c),
    memorableLines: makeMemorable(c),
  };
}

